148	pub fn check_queries_at_path(language: &Language, path: &Path) -> Result<()> {
149	    if path.exists() {
150	        for entry in WalkDir::new(path)
151	            .into_iter()
152	            .filter_map(std::result::Result::ok)
153	            .filter(|e| {
154	                e.file_type().is_file()
155	                    && e.path().extension().and_then(OsStr::to_str) == Some("scm")
156	                    && !e.path().starts_with(".")
157	            })
158	        {
159	            let filepath = entry.file_name().to_str().unwrap_or("");
160	            let content = fs::read_to_string(entry.path())
161	                .with_context(|| format!("Error reading query file {filepath:?}"))?;
162	            Query::new(language, &content)
163	                .with_context(|| format!("Error in query file {filepath:?}"))?;
164	        }
165	    }
166	    Ok(())
167	}
