+            .unwrap();
+    static ref COMMENT_REGEX: Regex = Regex::new(r"(?m)^\s*;.*$").unwrap();
+    static ref WHITESPACE_REGEX: Regex = Regex::new(r"\s+").unwrap();
+    static ref SEXP_FIELD_REGEX: Regex = Regex::new(r" \w+: \(").unwrap();
+    static ref POINT_REGEX: Regex = Regex::new(r"\s*\[\s*\d+\s*,\s*\d+\s*\]\s*").unwrap();
+}
+
+#[derive(Debug, PartialEq, Eq)]
+pub enum TestEntry {
+    Group {
+        name: String,
+        children: Vec<TestEntry>,
+        file_path: Option<PathBuf>,
+    },
+    Example {
+        name: String,
+        input: Vec<u8>,
+        output: String,
+        header_delim_len: usize,
+        divider_delim_len: usize,
+        has_fields: bool,
+        attributes: TestAttributes,
+    },
+}
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct TestAttributes {
+    pub skip: bool,
+    pub platform: bool,
+    pub fail_fast: bool,
+    pub error: bool,
+    pub languages: Vec<Box<str>>,
+}
+
+impl Default for TestEntry {
+    fn default() -> Self {
+        Self::Group {
+            name: String::new(),
+            children: Vec::new(),
+            file_path: None,
+        }
+    }
+}
+
+impl Default for TestAttributes {
+    fn default() -> Self {
+        Self {
+            skip: false,
+            platform: true,
+            fail_fast: false,
+            error: false,
+            languages: vec!["".into()],
+        }
+    }
+}
